import org.jsoup.parser.XmlTreeBuilder;
import org.junit.Test;
import static org.junit.Assert.*;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

public class XmlTreeBuilderTest {

    @Test
    public void parse_WithValidXml_ReturnsDocument() throws IOException {
        String xml = "<html><body>Hello World!</body></html>";
        Document document = new XmlTreeBuilder().parse(new StringReader(xml));
        assertNotNull(document);
    }

    @Test
    public void parse_WithInvalidXml_ReturnsNull() throws IOException {
        String xml = "<html><body>Hello World!</html>";
        Document document = new XmlTreeBuilder().parse(new StringReader(xml));
        assertNull(document);
    }

    @Test
    public void defaultSettings_returnsDefaultSettings() {
        ParseSettings settings = new XmlTreeBuilder().defaultSettings();
        assertNotNull(settings);
    }

    @Test
    public void initialiseParse_InitializesWithValidInputAndBaseUri() throws IOException, InterruptedException {
        String xml = "<html><body>Hello World!</body></html>";
        List<String> expectedTags = new ArrayList<>();
        expectedTags.add("html");
        expectedTags.add("body");
        expectedTags.add("/body");
        expectedTags.add("/html");

        Document document = new XmlTreeBuilder().initialiseParse(new StringReader(xml), "baseUri", null);
        assertTrue(document.tags.containsAll(expectedTags));
    }

    @Test
    public void initialiseParse_InitializesWithEmptyInputAndBaseUri() throws IOException, InterruptedException {
        List<String> expectedTags = new ArrayList<>();
        Document document = new XmlTreeBuilder().initialiseParse(new StringReader(""), "baseUri", null);
        assertTrue(document.tags.isEmpty());
    }

    @Test
    public void newInstance_returnsNewInstance() {
        XmlTreeBuilder instance1 = new XmlTreeBuilder();
        XmlTreeBuilder instance2 = instance1.newInstance();
        assertNotSame(instance1, instance2);
    }

    @Test
    public void process_ProcessesValidToken() {
        Token token = new Token(0, 10, "tag", "");
        assertTrue(new XmlTreeBuilder().process(token));
    }

    @Test
    public void process ProcessesInvalidToken_ThrowsException() {
        Token token = new Token(0, 10, null, "");
        try {
            new XmlTreeBuilder().process(token);
            fail("Expected an exception");
        } catch (AssertionError e) {
            // Expected
        }
    }

    @Test
    public void insertNode_InsertsNewNode() {
        Node node = new Node(0, 10, null, "");
        new XmlTreeBuilder().insertNode(node);
    }

    @Test
    public void insertStartTag_InsertsNewTag() {
        Token token = new Token(0, 10, "<tag", "");
        Element startTag = new XmlTreeBuilder().insert(token);
        assertNotNull(startTag);
        assertEquals("tag", startTag.name());
    }

    @Test
    public void insertComment_InsertsNewComment() {
        Token commentToken = new Token(0, 10, "#comment", "");
        new XmlTreeBuilder().insert(commentToken);
    }

    @Test
    public void insertCharacter_InsertsNewCharacter() {
        Token token = new Token(0, 10, "!", "");
        new XmlTreeBuilder().insert(token);
    }

    @Test
    public void insertDoctype_InsertsNewDoctype() {
        Token d = new Token(0, 10, "<!DOCTYPE>", "");
        new XmlTreeBuilder().insert(d);
    }

    @Test
    public void popStackToClose_ClosestEndTag() {
        Token endTag = new Token(0, 10, "</tag", "");
        new XmlTreeBuilder().popStackToClose(endTag);
    }

    @Test
    public void parseFragment_ParsesValidFragment() throws IOException {
        String xml = "<html><body>Hello World!</body></html>";
        List<Node> nodes = new XmlTreeBuilder().parseFragment(new StringReader(xml), "baseUri", null);
        assertEquals(2, nodes.size());
    }

    @Test
    public void parseFragment_ParsesEmptyFragment() throws IOException {
        List<Node> nodes = new XmlTreeBuilder().parseFragment(new StringReader(""), "baseUri", null);
        assertTrue(nodes.isEmpty());
    }
